<?php
namespace Tests\Feature;use App\Models\{Gift,Room,RoomGift,User};use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class RankingTest extends TestCase{use RefreshDatabase;public function test_rankings_order_senders_and_receivers_by_verified_gift_value():void{$one=User::factory()->create(['name'=>'One']);$two=User::factory()->create(['name'=>'Two']);$three=User::factory()->create(['name'=>'Three']);$room=Room::create(['name'=>'Ranked','host_user_id'=>$one->id]);$gift=Gift::create(['name_en'=>'Rose','name_ar'=>'وردة','emoji'=>'🌹','price'=>10]);RoomGift::create(['room_id'=>$room->id,'gift_id'=>$gift->id,'sender_id'=>$one->id,'recipient_id'=>$three->id,'price'=>100]);RoomGift::create(['room_id'=>$room->id,'gift_id'=>$gift->id,'sender_id'=>$two->id,'recipient_id'=>$three->id,'price'=>250]);$this->actingAs($one)->getJson('/api/rankings?period=weekly')->assertOk()->assertJsonPath('sent.0.user.name','Two')->assertJsonPath('sent.0.gold',250)->assertJsonPath('received.0.user.name','Three')->assertJsonPath('received.0.gold',350);}}
